{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE TABLE IF NOT EXISTS maplemonk.Final_sku_master ( MARKETPLACE_SKU STRING, marketplace STRING, marketplace_id STRING, new_sku STRING, color_sku STRING, parent_sku STRING, PRODUCT_name STRING, category STRING, product_sub_category STRING, image_url STRING, MRP FLOAT64 ); CREATE OR REPLACE TEMPORARY TABLE temp_extracted_data AS SELECT saleorderdto, JSON_EXTRACT_ARRAY(saleorderdto, \'$.saleOrderItems\') AS saleOrderItems, JSON_EXTRACT_ARRAY(saleorderdto, \'$.shippingPackages\') AS shippingPackages, JSON_EXTRACT_ARRAY(saleorderdto, \'$.returns\') AS returns, JSON_EXTRACT_SCALAR(saleorderdto, \'$.billingAddress.pincode\') AS PINCODE, JSON_EXTRACT_SCALAR(saleorderdto, \'$.channel\') AS marketplace, JSON_EXTRACT_SCALAR(saleorderdto, \'$.source\') AS source, JSON_EXTRACT_SCALAR(saleorderdto, \'$.code\') AS order_id, JSON_EXTRACT_SCALAR(saleorderdto, \'$.displayOrderCode\') AS reference_code, JSON_EXTRACT_SCALAR(saleorderdto, \'$.billingAddress.phone\') AS phone, JSON_EXTRACT_SCALAR(saleorderdto, \'$.billingAddress.name\') AS name, JSON_EXTRACT_SCALAR(saleorderdto, \'$.billingAddress.email\') AS email, datetime(timestamp_millis(CAST(JSON_EXTRACT_SCALAR(saleorderdto, \'$.updated\') AS int)), \"Asia/Kolkata\") AS SHIPPING_LAST_UPDATE_DATE, JSON_EXTRACT_SCALAR(saleorderdto, \'$.currencyCode\') AS currency, JSON_EXTRACT_SCALAR(saleorderdto, \'$.billingAddress.city\') AS city, JSON_EXTRACT_SCALAR(saleorderdto, \'$.billingAddress.state\') AS state, JSON_EXTRACT_SCALAR(saleorderdto, \'$.status\') AS ORDER_STATUS, datetime(timestamp_millis(CAST(JSON_EXTRACT_SCALAR(saleorderdto, \'$.displayOrderDateTime\') AS int)), \"Asia/Kolkata\") AS order_Date, CASE WHEN REPLACE(JSON_EXTRACT_SCALAR(saleorderdto, \'$.cod\'), \'\"\', \'\') = \'true\' THEN \'COD\' ELSE \'Prepaid\' END AS payment_mode, CASE WHEN REPLACE(JSON_EXTRACT_SCALAR(saleorderdto, \'$.code\'), \'\"\', \'\') = \'true\' THEN \'COD\' ELSE \'Prepaid\' END AS payment_method FROM maplemonk.UNICOMMERCE_TEKKITAKE_GET_ORDERS_BY_IDS ; CREATE OR REPLACE TEMPORARY TABLE temp_order_related AS SELECT ed.PINCODE as pincode, ed.marketplace as marketplace, ed.source as source, ed.order_id as ordeR_id, ed.reference_code reference_code, ed.phone phone, ed.name name, ed.email email, ed.SHIPPING_LAST_UPDATE_DATE SHIPPING_LAST_UPDATE_DATE, JSON_EXTRACT_SCALAR(item, \'$.itemSku\') AS sku, JSON_EXTRACT_SCALAR(item, \'$.sellerSkuCode\') AS Marketplace_sku, JSON_EXTRACT_SCALAR(item, \'$.channelProductId\') AS product_id, JSON_EXTRACT_SCALAR(item, \'$.itemName\') AS product_name, ed.currency currency, ed.city city, ed.state state, JSON_EXTRACT_SCALAR(item, \'$.statusCode\') as order_status, ed.order_Date ordeR_date, CAST(JSON_EXTRACT_SCALAR(item, \'$.shippingCharges\') AS FLOAT64) AS shipping_price, case when CAST(JSON_EXTRACT_SCALAR(item, \'$.packetNumber\') AS FLOAT64) > 0 then CAST(JSON_EXTRACT_SCALAR(item, \'$.packetNumber\') AS FLOAT64) else cast(JSON_EXTRACT_SCALAR(shippingPackages,\'$.noOfItems\') as float64) end AS SUBORDER_QUANTITY, CAST(JSON_EXTRACT_SCALAR(item, \'$.discount\') AS FLOAT64) AS discount, CAST(JSON_EXTRACT_SCALAR(item, \'$.totalIntegratedGst\') AS FLOAT64) AS tax, CAST(JSON_EXTRACT_SCALAR(item, \'$.sellingPrice\') AS FLOAT64) AS SELLING_PRICE, JSON_EXTRACT_SCALAR(item, \'$.shippingPackageCode\') AS shippingPackageCode, JSON_EXTRACT_SCALAR(item, \'$.shippingPackageStatus\') AS shippingPackageStatus, JSON_EXTRACT_SCALAR(item, \'$.code\') AS saleOrderItemCode, CAST(JSON_EXTRACT_SCALAR(item, \'$.id\') AS STRING) AS SALES_ORDER_ITEM_ID, JSON_EXTRACT_SCALAR(item, \'$.facilityName\') AS warehouse_name, JSON_EXTRACT_SCALAR(shippingPackages,\'$.trackingNumber\') AS AWB, datetime(timestamp_millis(CAST(JSON_EXTRACT_SCALAR(shippingPackages,\'$.invoiceDate\') AS int)), \"Asia/Kolkata\") AS invoiceDate, JSON_EXTRACT_SCALAR(shippingPackages,\'$.invoiceCode\') invoiceCode, ed.payment_mode, ed.payment_method FROM temp_extracted_data ed LEFT JOIN UNNEST(ed.saleOrderItems) AS item LEFT JOIN UNNEST(ed.shippingPackages) AS shippingPackages; CREATE OR REPLACE TEMPORARY TABLE temp_shipping_related AS WITH extracted_items AS ( SELECT REPLACE(JSON_EXTRACT_SCALAR(A, \'$.shippingProvider\'), \'\"\', \'\') AS courier, REPLACE(JSON_EXTRACT_SCALAR(A, \'$.status\'), \'\"\', \'\') AS shipping_status, datetime(timestamp_millis(CAST(JSON_EXTRACT_SCALAR(A, \'$.dispatched\') AS int)), \"Asia/Kolkata\") AS dispatched, datetime(timestamp_millis(CAST(JSON_EXTRACT_SCALAR(A, \'$.delivered\') AS int)), \"Asia/Kolkata\") AS delivered, JSON_EXTRACT_SCALAR(A, \'$.code\') AS shippingPackageCode, c.order_id, JSON_EXTRACT(A, \'$.items\') AS items FROM temp_extracted_data c LEFT JOIN UNNEST(c.shippingPackages) A ) SELECT c.*, cast(JSON_EXTRACT_SCALAR(value, \'$.quantity\') AS int64) AS shippedQuantity, JSON_EXTRACT_SCALAR(value, \'$.itemSku\') AS itemSku, FROM extracted_items c left join UNNEST(REGEXP_EXTRACT_ALL(items, r\'\{[^{}]+\}\')) AS value; CREATE OR REPLACE TEMPORARY TABLE temp_returns AS WITH extracted_return_data AS ( SELECT ed.order_id, ed.reference_code, JSON_EXTRACT_ARRAY(A, \'$.returnItems\') AS returnItems FROM temp_extracted_data ed LEFT JOIN UNNEST(ed.returns) AS A ) SELECT erd.order_id AS ordeR_id, erd.reference_code, REPLACE(JSON_EXTRACT_SCALAR(B, \'$.saleOrderItemCode\'), \'\"\', \'\') AS saleOrderItemCode, REPLACE(JSON_EXTRACT_SCALAR(B, \'$.itemSku\'), \'\"\', \'\') AS itemSku FROM extracted_return_data erd LEFT JOIN UNNEST(erd.returnItems) AS B WHERE REPLACE(JSON_EXTRACT_SCALAR(B, \'$.saleOrderItemCode\'), \'\"\', \'\') IS NOT NULL; create or replace table maplemonk.TEKKITAKE_UNICOMMERCE_fact_items_intermediate_final as SELECT o.pincode, o.marketplace, o.source, o.order_id, o.reference_code, o.phone, o.name, o.email, o.SHIPPING_LAST_UPDATE_DATE, o.sku, o.Marketplace_sku, o.product_id, o.product_name, o.currency, o.city, o.state, o.ORDER_STATUS, invoiceCode, invoiceDate, o.order_date , o.shipping_price, o.SUBORDER_QUANTITY, o.discount, o.tax, ifnull(o.SELLING_PRICE,0) + ifnull(O.shipping_price,0) as SELLING_PRICE, o.shippingPackageCode, o.shippingPackageStatus, o.saleOrderItemCode, o.SALES_ORDER_ITEM_ID, o.AWB, o.warehouse_name, o.payment_mode, o.payment_method, s.courier, s.shipping_status, s.shippedQuantity, s.dispatched AS Dispatch_date, s.delivered AS Delivered_Date, CASE WHEN r.itemSku IS NOT NULL THEN 1 ELSE 0 END AS return_flag, CASE WHEN (CASE WHEN r.itemSku IS NOT NULL THEN 1 ELSE 0 END) = 1 THEN (CASE WHEN LOWER(o.marketplace) LIKE \'%myntra%\' THEN s.shippedQuantity ELSE o.SUBORDER_QUANTITY END) ELSE 0 END AS return_quantity, CASE WHEN order_status = \'CANCELLED\' THEN CASE WHEN LOWER(o.marketplace) LIKE \'%myntra%\' THEN s.shippedQuantity ELSE o.SUBORDER_QUANTITY END ELSE 0 END AS cancelled_quantity, CASE WHEN ROW_NUMBER() OVER (PARTITION BY phone ORDER BY order_date ASC) = 1 THEN \'New\' ELSE \'Repeat\' END AS new_customer_flag, FIRST_VALUE(product_name) OVER (PARTITION BY phone ORDER BY order_date ASC) AS acquisition_product, CASE WHEN UPPER(order_status) = \'COMPLETE\' THEN CAST(s.delivered AS DATE) - CAST(order_date AS DATE) ELSE CAST(CURRENT_DATE AS DATE) - CAST(order_date AS DATE) END AS days_in_shipment, FROM temp_order_related o LEFT JOIN temp_shipping_related s ON o.shippingPackageCode = s.shippingPackageCode AND o.sku = s.itemSku AND o.order_id = s.order_id LEFT JOIN temp_returns r ON r.saleOrderItemCode = o.saleOrderItemCode AND r.order_id = o.order_id WHERE o.marketplace <> \'CUSTOM\' ; create or replace table maplemonk.TEKKITAKE_customerID_test_Final as with new_phone_numbers as ( select contact_num ,9700000000 + row_number() over( order by contact_num asc ) as maple_monk_id from ( select distinct SUBSTR(REGEXP_REPLACE(REPLACE(phone, \' \', \'\'),\'[^a-zA-Z0-9]\',\'\'),-10) as contact_num from maplemonk.TEKKITAKE_UNICOMMERCE_fact_items_intermediate_final ) a ), int as ( select contact_num,email,coalesce(maple_monk_id,id2) as maple_monk_id from ( select contact_num, email,maple_monk_id,9800000000+row_number() over(partition by maple_monk_id is NULL order by email asc ) as id2 from ( select distinct coalesce(p.contact_num,SUBSTR(REGEXP_REPLACE(REPLACE(e.contact_num, \' \', \'\'),\'[^a-zA-Z0-9]\',\'\'),-10)) as contact_num, e.email,maple_monk_id from ( select replace(phone,\' \',\'\') as contact_num,email from maplemonk.TEKKITAKE_UNICOMMERCE_fact_items_intermediate_final ) e left join new_phone_numbers p on p.contact_num = SUBSTR(REGEXP_REPLACE(REPLACE(e.contact_num, \' \', \'\'),\'[^a-zA-Z0-9]\',\'\'),-10) ) a ) b ) select contact_num,email,case when email is not null and email <> \'\' then min(maple_monk_id) over (partition by email ) else maple_monk_id end maple_monk_id from int where coalesce(contact_num,email) is not NULL; create or replace table maplemonk.TEKKITAKE_unicommerce_fact_items as select coalesce(c.maple_monk_id,c.maple_monk_id) customer_id, o.*, CASE WHEN marketplace IN (\'TEKKITAKE_MEESHO\') THEN \'Meesho\' WHEN marketplace IN (\'FLIPKART\', \'FK_BNG\') THEN \'Flipkart\' WHEN marketplace IN (\'TEKKITAKE_AJIO\') THEN \'Ajio\' WHEN marketplace IN (\'TEKKITAKE_MYNTRA\') THEN \'Myntra\' WHEN marketplace LIKE \'AMAZON%\' THEN \'Amazon\' WHEN marketplace LIKE \'SHOPIFY%\' THEN \'Shopify\' WHEN marketplace = \'TATACLIQ1\' THEN \'TataCliq\' ELSE \'Others\' END AS mapped_marketplace, min(order_date) over(partition by coalesce(c.maple_monk_id,c.maple_monk_id)) as acquisition_date from maplemonk.TEKKITAKE_UNICOMMERCE_fact_items_intermediate_final o left join (select distinct contact_num phone,maple_monk_id from maplemonk.TEKKITAKE_customerID_test_Final )c on replace(c.phone,\' \',\'\') = replace(o.phone,\' \',\'\') where o.order_date is not null; CREATE OR REPLACE TABLE maplemonk.TEKKITAKE_unicommerce_fact_items_TEMP_Category as select fi.*, p.SKUCODE AS SKU_CODE, upper(p.PRODUCT_name) as PRODUCT_NAME_Final, Upper(p.CATEGORY) AS Product_Category, p.product_sub_category, Upper(p.commonsku) AS commonsku, p.color_sku, p.parent_sku, p.image_url, p1.marketplace_id, p.mrp from maplemonk.TEKKITAKE_unicommerce_fact_items fi left join (select MARKETPLACE_SKU skucode, new_sku as commonsku, color_sku, parent_sku, PRODUCT_name, category, cast(null as string) AS product_sub_category, image_url, MRP, cast(null as string) from maplemonk.Final_sku_master ) p on lower(fi.sku) = lower(p.commonsku) left join (select MARKETPLACE_SKU skucode, Marketplace_ID, marketplace, new_sku as commonsku from maplemonk.Final_sku_master ) p1 on lower(trim(fi.sku)) = lower(trim(p1.commonsku)) and lower(trim(fi.mapped_marketplace)) = lower(trim(p1.marketplace)) ; CREATE OR REPLACE TABLE maplemonk.TEKKITAKE_unicommerce_fact_items AS SELECT * FROM ( select *, row_number() over (partition by reference_code,saleorderitemcode order by SHIPPING_LAST_UPDATE_DATE desc) rw1 from maplemonk.TEKKITAKE_unicommerce_fact_items_TEMP_Category ) where rw1 = 1; CREATE OR REPLACE TEMPORARY TABLE temp_extracted_data_return AS SELECT saleorderdto, JSON_EXTRACT_ARRAY(saleorderdto, \'$.returns\') AS returns, JSON_EXTRACT_ARRAY(saleorderdto, \'$.returns.returnItems\') AS returnItems, JSON_EXTRACT_SCALAR(saleorderdto, \'$.channel\') AS Marketplace, JSON_EXTRACT_SCALAR(saleorderdto, \'$.source\') AS Source, JSON_EXTRACT_SCALAR(saleorderdto, \'$.code\') AS order_id, JSON_EXTRACT_SCALAR(saleorderdto, \'$.displayOrderCode\') AS reference_code, JSON_EXTRACT_SCALAR(saleorderdto, \'$.billingAddress.phone\') AS phone, JSON_EXTRACT_SCALAR(saleorderdto, \'$.billingAddress.email\') AS email, datetime(timestamp_millis(CAST(JSON_EXTRACT_SCALAR(saleorderdto, \'$.displayOrderDateTime\') AS int)), \"Asia/Kolkata\") AS order_date FROM maplemonk.UNICOMMERCE_TEKKITAKE_GET_ORDERS_BY_IDS_final ; CREATE OR REPLACE TEMPORARY TABLE temp_return_data AS SELECT ed.marketplace, ed.source, ed.order_id, ed.phone, ed.email, ed.order_date, ed.reference_code, REPLACE(JSON_EXTRACT_SCALAR(A, \'$.code\'), \'\"\', \'\') AS return_display_code, REPLACE(JSON_EXTRACT_SCALAR(A, \'$.statusCode\'), \'\"\', \'\') AS return_status, REPLACE(JSON_EXTRACT_SCALAR(B, \'$.itemName\'), \'\"\', \'\') AS return_Item, REPLACE(JSON_EXTRACT_SCALAR(B, \'$.itemSku\'), \'\"\', \'\') AS return_sku, REPLACE(JSON_EXTRACT_SCALAR(B, \'$.saleOrderItemCode\'), \'\"\', \'\') AS return_saleOrderItemCode, REPLACE(JSON_EXTRACT_SCALAR(B, \'$.inventoryType\'), \'\"\', \'\') AS return_inventory_type, datetime(timestamp_millis(CAST(JSON_EXTRACT_SCALAR(A, \'$.inventoryReceivedDate\') AS int)), \"Asia/Kolkata\") AS inventory_received_date, datetime(timestamp_millis(CAST(JSON_EXTRACT_SCALAR(A, \'$.returnCompletedDate\') AS int)), \"Asia/Kolkata\") AS return_complete_date, REPLACE(JSON_EXTRACT_SCALAR(A, \'$.returnInvoiceDisplayCode\'), \'\"\', \'\') AS return_invoice_display_code, REPLACE(JSON_EXTRACT_SCALAR(A, \'$.shippingProvider\'), \'\"\', \'\') AS return_courier, REPLACE(JSON_EXTRACT_SCALAR(A, \'$.providerStatus\'), \'\"\', \'\') AS return_provider_shipping_status, REPLACE(JSON_EXTRACT_SCALAR(A, \'$.trackingNumber\'), \'\"\', \'\') AS return_tracking_number, REPLACE(JSON_EXTRACT_SCALAR(A, \'$.type\'), \'\"\', \'\') AS return_type FROM temp_extracted_data_return ed LEFT JOIN UNNEST(ed.returns) AS A LEFT JOIN UNNEST(JSON_EXTRACT_ARRAY(A,\'$.returnItems\')) AS B qualify row_number() over (partition by reference_code,REPLACE(JSON_EXTRACT_SCALAR(B, \'$.saleOrderItemCode\'), \'\"\', \'\') order by order_date asc)=1; CREATE OR REPLACE TABLE maplemonk.TEKKITAKE_UNICOMMERCE_RETURNS_INTERMEDIATE AS SELECT rd.marketplace, rd.source, rd.order_id, rd.phone, rd.email, rd.order_date, rd.reference_code, case when rd.return_display_code is not null then 1 else 0 end as return_flag, rd.return_display_code, rd.return_status, rd.inventory_received_date, rd.return_complete_date, rd.return_invoice_display_code, rd.return_courier, rd.return_provider_shipping_status, rd.return_tracking_number, rd.return_type, rd.return_saleOrderItemCode, rd.return_sku, rd.return_Item, rd.return_inventory_type, CASE WHEN marketplace IN (\'TEKKITAKE_MEESHO\') THEN \'Meesho\' WHEN marketplace IN (\'FLIPKART\', \'FK_BNG\') THEN \'Flipkart\' WHEN marketplace IN (\'TEKKITAKE_AJIO\') THEN \'Ajio\' WHEN marketplace IN (\'TEKKITAKE_MYNTRA\') THEN \'Myntra\' WHEN marketplace LIKE \'AMAZON%\' THEN \'Amazon\' WHEN marketplace LIKE \'SHOPIFY%\' THEN \'Shopify\' WHEN marketplace = \'TATACLIQ1\' THEN \'TataCliq\' ELSE \'Others\' END AS mapped_marketplace, FROM temp_return_data rd ; create or replace table maplemonk.TEKKITAKE_UNICOMMERCE_RETURNS as select ri.*, p.SKUCODE AS SKU_CODE, upper(p.PRODUCT_name) as PRODUCT_NAME_Final, Upper(p.CATEGORY) AS Product_Category, p.product_sub_category, Upper(p.commonsku) AS commonsku, p.color_sku, p.parent_sku, p.image_url, p.marketplace_id, p.mrp from maplemonk.TEKKITAKE_UNICOMMERCE_RETURNS_INTERMEDIATE ri left join (select MARKETPLACE_SKU skucode, marketplace, marketplace_id, new_sku as commonsku, color_sku, parent_sku, PRODUCT_name, category, cast(null as string) AS product_sub_category, image_url, MRP from maplemonk.Final_sku_master ) p on lower(ri.return_sku) = lower(p.commonsku) and lower(ri.mapped_marketplace) = lower(p.marketplace) ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            